REPLACE INTO `quest_template_locale` SET `ID`='13833', `Locale`='zhCN', `Title`='危险的美食', `Details`='最好的钓鱼地点总是最危险的。冬拥湖里有无数的战利品等待着大胆的垂钓者。$B$B事实上，只有在冬拥湖才能钓到传说中最危险也最美味的恐怖鱼。给我带些这种鱼来，然后我们再好好聊聊。', `Objectives`='将10条恐怖鱼交给达拉然城中的玛西娅·切斯。', `EndText`='', `CompletedText`='去达拉然找玛西娅·切斯。', `ObjectiveText1`='', `ObjectiveText2`='', `ObjectiveText3`='', `ObjectiveText4`='';
REPLACE INTO `quest_offer_reward_locale` SET `ID`='13833', `Locale`='zhCN', `RewardText`='你很勇敢，$N。我希望你没有为了弄出钓鱼点而受到什么损伤。如果你还热中于钓鱼的话，明天来找我，我们可以再聊聊。';
